mapper.select:
select product_name
from fin_product
where product_id = #{productId}
  and tenant_id = #{tenantId}
  and dept_id = #{deptId}
  and del_flag = '0'

select sale_price
from fin_product
where product_id = #{productId}
  and tenant_id = #{tenantId}
  and dept_id = #{deptId}
  and del_flag = '0'

select o.purchase_id, o.tenant_id, o.dept_id, o.period_id, o.purchase_no, o.customer_type,
       o.member_id, o.customer_id, o.customer_name, o.customer_phone, o.identity_mode, o.purchase_date,
       o.identity_confirmed, o.total_amount, o.paid_amount, o.receivable_amount,
       o.payment_status, o.delivery_status, o.order_status, o.idempotency_key,
       coalesce(i.purchase_quantity, 0) purchase_quantity, coalesce(i.gift_quantity, 0) gift_quantity
from mem_purchase_order o
left join (select purchase_id, sum(purchase_quantity) purchase_quantity, sum(gift_quantity) gift_quantity
           from mem_purchase_item where del_flag = '0' group by purchase_id) i on i.purchase_id = o.purchase_id
left join mem_member m on m.member_id = o.member_id

    o.del_flag = '0' and o.order_status <> '4'
    and o.tenant_id = #{tenantId}
    and o.dept_id = #{deptId}
    and o.purchase_no like concat('%', #{purchaseNo}, '%')
    and o.period_id = #{periodId}
    and o.member_id = #{memberId}
    and m.member_no like concat('%', #{memberNo}, '%')
    and o.customer_name like concat('%', #{customerName}, '%')
    and o.customer_type = #{customerType}
    and o.payment_status = #{paymentStatus}
    and o.delivery_status = #{deliveryStatus}
    and o.purchase_date >= #{beginTime}
    and o.purchase_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

order by o.purchase_id desc

select count(distinct o.purchase_id) as purchaseOrderCount,
       coalesce(sum(o.total_amount), 0) as totalAmount,
       coalesce(sum(o.paid_amount), 0) as paidAmount,
       coalesce(sum(o.receivable_amount), 0) as receivableAmount,
       coalesce(sum(i.purchase_quantity), 0) as purchaseQuantity,
       coalesce(sum(i.gift_quantity), 0) as giftQuantity,
       coalesce(sum(i.delivered_quantity), 0) as deliveredQuantity
from mem_purchase_order o
left join (select purchase_id, sum(purchase_quantity) purchase_quantity, sum(gift_quantity) gift_quantity, sum(delivered_quantity) delivered_quantity
           from mem_purchase_item where del_flag = '0' group by purchase_id) i on i.purchase_id = o.purchase_id
left join mem_member m on m.member_id = o.member_id

    o.del_flag = '0'
    and o.order_status <> '4'
    and o.tenant_id = #{tenantId}
    and o.dept_id = #{deptId}
    and o.period_id = #{periodId}
    and o.member_id = #{memberId}
    and m.member_no like concat('%', #{memberNo}, '%')
    and o.customer_name like concat('%', #{customerName}, '%')
    and o.customer_type = #{customerType}
    and o.purchase_no like concat('%', #{purchaseNo}, '%')
    and o.payment_status = #{paymentStatus}
    and o.delivery_status = #{deliveryStatus}
    and o.purchase_date >= #{beginTime}
    and o.purchase_date < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

mapper.update:
update mem_purchase_payment
set payment_amount = #{paymentAmount}, payment_method = #{paymentMethod},
    payment_date = #{paymentDate}, remark = #{remark}
where payment_id = #{paymentId} and purchase_id = #{purchaseId}
  and tenant_id = #{tenantId} and dept_id = #{deptId} and status = '1'

update mem_purchase_order set order_status = '4', update_by = #{updateBy}, update_time = sysdate()
where purchase_id = #{purchaseId} and tenant_id = #{tenantId} and dept_id = #{deptId}
  and del_flag = '0' and order_status <> '4'
